CREATE OR REPLACE FUNCTION public.username_available(p_username text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_username is null or p_username !~ '^[a-z0-9_]{3,30}$' then 'invalid'
    when exists (select 1 from public.profiles p where p.username = p_username)
      or exists (select 1 from private.reserved_usernames r where r.username = p_username)
      or exists (select 1 from private.username_tombstones t where t.username = p_username)
      then 'taken'
    else 'available'
  end;
$function$;

grant execute on function public.username_available(p_username text) to anon;
grant execute on function public.username_available(p_username text) to authenticated;
grant execute on function public.username_available(p_username text) to service_role;
